// Desde el 24 nov 2026 a las marcas se les envía la propuesta Presenting Partner (sin precios)
// en lugar del media kit del Xperience. También corrige los seguimientos ya programados.
export function linkPropuesta(text) {
  if (!text) return text;
  return text.replace(/https:\/\/www\.gamelobby\.live\/mediakit-xperience\?marca=([^\s#]*)(#stands)?/g,
    "https://www.gamelobby.live/propuesta/presenting-partner?marca=$1")
    .replace(/Media kit: (https:\/\/www\.gamelobby\.live\/propuesta\/)/g, "Propuesta: $1");
}
